    <div class="growth-grid"><section class="dashboard-card growth-card"><div class="section-card-heading"><div><span class="card-label">الميزة الأولى</span><h2>أهدافي ومراحلي</h2></div><span class="growth-progress"><?= $doneGoals ?> / <?= count($goals) ?> مكتملة</span></div>
        <form method="post" action="/growth/goal" class="growth-add-form"><?= csrf_field() ?><label class="field"><span>هدف جديد</span><input name="title" maxlength="180" placeholder="مثال: إنجاز مشروع تطبيقي أو تطوير استراتيجية جديدة" required></label><label class="field"><span>موعد مستهدف</span><input type="date" name="target_date"></label><button class="button button-gold" type="submit">إضافة الهدف</button></form>
        <div class="goal-list"><?php if ($goals): foreach ($goals as $goal): ?><div class="goal-row <?= $goal['status']==='done'?'is-done':'' ?>"><form method="post" action="/growth/goal/<?= (int)$goal['id'] ?>/toggle"><?= csrf_field() ?><button class="goal-check" type="submit" aria-label="تغيير حالة الهدف">✓</button></form><div><strong><?= e($goal['title']) ?></strong><?php if ($goal['target_date']): ?><small>الموعد: <?= e($goal['target_date']) ?></small><?php endif; ?></div><span><?= $goal['status']==='done'?'مكتمل':'قيد العمل' ?></span></div><?php endforeach; else: ?><p class="empty-note">أضف أول هدف لك، واجعله واضحًا وقابلًا للإنجاز.</p><?php endif; ?></div>
    </section><section class="dashboard-card growth-card"><div class="section-card-heading"><div><span class="card-label">الميزة الثانية</span><h2>سجل التأمل والتعلم</h2></div><span class="growth-icon">✦</span></div><p class="helper-note">اكتب ما نجح، ما يحتاج تحسينًا، والخطوة التالية. هذا السجل خاص بك ولا يظهر في رابط المشاركة.</p><form method="post" action="/growth/reflection"><?= csrf_field() ?><label class="field"><span>سؤال التأمل</span><select name="prompt"><option><?= $isTeacher?'ما الاستراتيجية التي أثرت في تعلم طلابي؟':'ما المهارة الجديدة التي أتقنتها؟' ?></option><option>ما التحدي الذي واجهته؟ وكيف تعاملت معه؟</option><option>ما الخطوة الصغيرة التالية التي سأجربها؟</option></select></label><label class="field"><span>تأملي اليوم</span><textarea name="body" rows="6" maxlength="4000" placeholder="اكتب ملاحظتك بصوتك الخاص..." required></textarea></label><button class="button button-outline-navy" type="submit">حفظ التأمل</button></form></section></div>
